            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Decoding(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .AddressParse(
            address: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
