        case 8: return .InvalidNftCreatorPublicKey(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .InvalidTokenParameters(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 10: return .TransactionCreation(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 11: return .SignedTransactionCreation(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 12: return .PartiallySignedTransactionCreation(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 13: return .InputSigning(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 14: return .KeyDerivation(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 15: return .Sighash(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 16: return .MessageSigning(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 17: return .SignatureVerification(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 18: return .InvalidHtlcSecretHash(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 19: return .UnexpectedHtlcSpendType
        case 20: return .NoInputOutpointFound
        case 21: return .InvalidWitnessCount
        case 22: return .SizeEstimation(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 23: return .EffectiveBalance(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 24: return .OrdersV1NotActivated
        case 25: return .IntentMessageNotUtf8
        case 26: return .InvalidAmount(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 27: return .InvalidTransactionId(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 28: return .IntentVerification(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 29: return .Json(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BindingsError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidMnemonic(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Decoding(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .AddressParse(address,detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(address, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case .InvalidKeyIndex:
            writeInt(&buf, Int32(4))
        
        
        case .FixedTotalSupplyWithoutAmount:
            writeInt(&buf, Int32(5))
        
        
        case let .InvalidMarginRatio(ratio):
            writeInt(&buf, Int32(6))
            FfiConverterUInt16.write(ratio, into: &buf)
            
        
        case .ZeroMultisigRequiredSignatures:
            writeInt(&buf, Int32(7))
        
        
        case let .InvalidNftCreatorPublicKey(detail):
            writeInt(&buf, Int32(8))
