        case let .KeyDerivation(detail):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Sighash(detail):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .MessageSigning(detail):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .SignatureVerification(detail):
